window.ENTRY_ASSETS["lp-local-llm-v2--qwen38-code-0253--1792561438954-2fnlc"]={"html":"\n\n\u003c!doctype html>\n\u003chtml lang=\"ja\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n\u003cmeta name=\"color-scheme\" content=\"dark\">\n\u003ctitle>ローカルLLMという選択肢 | 自分のPCで動かす\u003c/title>\n\u003cmeta name=\"description\" content=\"ローカルLLMを自分のPCで動かす選択肢。手元で試す楽しさ、モデルを選べる自由、データの扱いを自分で設計できること。導入の4ステップと注意点まで。\">\n\u003cstyle>\n/* ============ tokens ============ */\n:root{\n  --bg:#06080f;\n  --bg-2:#0a0e1b;\n  --panel:#0d1224;\n  --ink:#eaf0ff;\n  --ink-2:#aab6d4;\n  --ink-3:#7a87a8;\n  --line:rgba(150,175,225,.18);\n  --acc:#79f2c0;      /* mint */\n  --acc-2:#7fa6ff;    /* blue */\n  --acc-3:#f6c268;    /* amber */\n  --card:rgba(255,255,255,.045);\n  --glow:0 0 0 1px rgba(121,242,192,.25), 0 18px 50px -20px rgba(121,242,192,.35);\n  --sans:\"Hiragino Kaku Gothic ProN\",\"BIZ UDPGothic\",\"Yu Gothic UI\",\"Noto Sans JP\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:ui-monospace,\"Cascadia Mono\",Consolas,\"SFMono-Regular\",\"Courier New\",monospace;\n  --pad:clamp(18px,4.4vw,44px);\n  --maxw:1140px;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;background:var(--bg);-webkit-text-size-adjust:100%}\nbody{\n  margin:0;color:var(--ink);font-family:var(--sans);\n  font-size:clamp(15px,1.02vw,16.5px);line-height:1.85;letter-spacing:.02em;\n  background:\n    radial-gradient(1100px 620px at 78% -10%, rgba(127,166,255,.18), transparent 60%),\n    radial-gradient(900px 700px at 6% 12%, rgba(121,242,192,.14), transparent 62%),\n    var(--bg);\n  overflow-x:hidden;\n}\nh1,h2,h3,p,ul,ol{margin:0;padding:0}\nul,ol{list-style:none}\na{color:inherit;text-decoration:none}\nh1,h2,h3{line-height:1.3;font-weight:700;letter-spacing:.01em}\n.sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}\n.skip{position:absolute;left:-9999px;top:0;z-index:99;background:var(--acc);color:#04121a;padding:10px 16px;font-weight:700}\n.skip:focus{left:12px;top:12px}\n:focus-visible{outline:2px solid var(--acc);outline-offset:3px;border-radius:4px}\n.wrap{width:100%;max-width:var(--maxw);margin-inline:auto;padding-inline:var(--pad)}\n\n/* ============ topbar / progress ============ */\n.topbar{\n  position:fixed;inset:0 0 auto 0;z-index:40;display:flex;align-items:center;gap:18px;\n  height:64px;padding-inline:clamp(14px,4vw,34px);\n  background:linear-gradient(180deg, rgba(6,8,15,.92), rgba(6,8,15,.55) 70%, transparent);\n  backdrop-filter:blur(8px);\n}\n.brand{display:flex;align-items:center;gap:10px;font-family:var(--mono);font-size:12px;letter-spacing:.24em;color:var(--ink-2)}\n.brand svg{width:26px;height:26px;flex:none;filter:drop-shadow(0 0 8px rgba(121,242,192,.5))}\n.brand b{color:var(--ink);font-weight:700}\n.topnav{margin-left:auto;display:flex;gap:6px}\n.topnav a{\n  position:relative;display:block;padding:8px 11px;font-size:12.5px;letter-spacing:.08em;color:var(--ink-3);\n  transition:color .3s ease;\n}\n.topnav a::after{\n  content:\"\";position:absolute;left:11px;right:11px;bottom:4px;height:1px;background:var(--acc);\n  transform:scaleX(0);transform-origin:left;transition:transform .35s cubic-bezier(.2,.7,.2,1);\n}\n.topnav a:hover,.topnav a:focus-visible,.topnav a.active{color:var(--ink)}\n.topnav a:hover::after,.topnav a:focus-visible::after,.topnav a.active::after{transform:scaleX(1)}\n.mbtn{\n  font-family:var(--mono);font-size:11px;letter-spacing:.14em;color:var(--ink-2);cursor:pointer;\n  background:rgba(255,255,255,.05);border:1px solid var(--line);border-radius:999px;padding:7px 13px;\n  display:flex;align-items:center;gap:8px;transition:background .3s ease,color .3s ease,border-color .3s ease;\n}\n.mbtn i{width:7px;height:7px;border-radius:50%;background:var(--acc);box-shadow:0 0 10px var(--acc);animation:blink 2.2s ease-in-out infinite}\n.mbtn[aria-pressed=\"true\"] i{background:var(--ink-3);box-shadow:none;animation:none}\n.mbtn:hover{color:var(--ink);border-color:rgba(121,242,192,.5);background:rgba(121,242,192,.08)}\n.progress{position:fixed;inset:64px 0 auto 0;height:2px;z-index:39;background:rgba(255,255,255,.07)}\n.progress span{display:block;height:100%;background:linear-gradient(90deg,var(--acc),var(--acc-2));transform:scaleX(0);transform-origin:left}\n\n/* ============ hero ============ */\n.hero{position:relative;min-height:100vh;min-height:100svh;display:flex;align-items:center;padding:110px 0 60px;isolation:isolate}\n#net{position:absolute;inset:0;z-index:-2;width:100%;height:100%;opacity:.95}\n.hero-veil{\n  position:absolute;inset:0;z-index:-1;pointer-events:none;\n  background:\n    radial-gradient(120% 90% at 50% 40%, transparent 30%, rgba(6,8,15,.6) 70%, var(--bg) 100%),\n    repeating-linear-gradient(90deg, rgba(150,175,225,.07) 0 1px, transparent 1px 88px),\n    repeating-linear-gradient(0deg, rgba(150,175,225,.05) 0 1px, transparent 1px 88px);\n  mask-image:radial-gradient(115% 90% at 50% 42%, #000 40%, transparent 78%);\n}\n.hero-inner{display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);gap:clamp(26px,4vw,58px);align-items:center;width:100%}\n.eyebrow{\n  font-family:var(--mono);font-size:11.5px;letter-spacing:.3em;color:var(--acc);\n  display:flex;align-items:center;gap:12px;margin-bottom:22px;text-transform:uppercase;\n}\n.eyebrow::before{content:\"\";width:38px;height:1px;background:linear-gradient(90deg,var(--acc),transparent)}\nh1{font-size:clamp(30px,5.1vw,60px);letter-spacing:0}\nh1 .ln{display:block;overflow:hidden}\nh1 .ln>span{display:block;animation:rise 1.05s cubic-bezier(.19,.86,.24,1) both}\nh1 .ln:nth-child(1)>span{animation-delay:.05s}\nh1 .ln:nth-child(2)>span{animation-delay:.18s}\nh1 .ln:nth-child(3)>span{animation-delay:.31s}\nh1 em{\n  font-style:normal;position:relative;\n  background:linear-gradient(96deg,var(--acc),var(--acc-2) 60%,#fff);\n  -webkit-background-clip:text;background-clip:text;color:transparent;\n}\nh1 em::after{\n  content:\"\";position:absolute;left:0;right:0;bottom:.02em;height:.14em;\n  background:linear-gradient(90deg,rgba(121,242,192,.75),rgba(127,166,255,0));\n  transform:scaleX(0);transform-origin:left;animation:swipe 1.1s .8s cubic-bezier(.19,.86,.24,1) forwards;\n}\n.lead{margin-top:22px;color:var(--ink-2);max-width:34em;animation:rise 1s .45s cubic-bezier(.19,.86,.24,1) both}\n.rot{\n  margin-top:18px;font-family:var(--mono);font-size:12.5px;letter-spacing:.1em;color:var(--ink-3);\n  display:flex;align-items:center;gap:10px;animation:rise 1s .55s cubic-bezier(.19,.86,.24,1) both;\n}\n.rot span.hash{color:var(--acc-2)}\n#rotWord{color:var(--ink);padding:2px 10px;border:1px solid var(--line);border-radius:4px;background:rgba(127,166,255,.08);display:inline-block}\n#rotWord.pop{animation:pop .5s cubic-bezier(.2,.9,.2,1)}\n.cta-row{margin-top:30px;display:flex;flex-wrap:wrap;gap:12px;animation:rise 1s .65s cubic-bezier(.19,.86,.24,1) both}\n.btn{\n  position:relative;overflow:hidden;display:inline-flex;align-items:center;gap:10px;\n  padding:15px 26px;font-weight:700;font-size:14.5px;letter-spacing:.04em;border-radius:6px;\n  border:1px solid transparent;transition:transform .3s cubic-bezier(.2,.8,.2,1),box-shadow .3s ease,border-color .3s ease,color .3s ease;\n}\n.btn svg{width:15px;height:15px;flex:none;transition:transform .35s cubic-bezier(.2,.8,.2,1)}\n.btn.primary{background:linear-gradient(120deg,var(--acc),#4fdca9);color:#04140e;box-shadow:0 14px 34px -16px rgba(121,242,192,.9)}\n.btn.primary::after{content:\"\";position:absolute;top:0;left:-60%;width:38%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.55),transparent);transform:translateX(-120%)}\n.btn.primary:hover,.btn.primary:focus-visible{transform:translateY(-3px);box-shadow:0 22px 44px -16px rgba(121,242,192,.85)}\n.btn.primary:hover::after,.btn.primary:focus-visible::after{transform:translateX(360%);transition:transform .75s ease}\n.btn.ghost{border-color:var(--line);color:var(--ink);background:rgba(255,255,255,.04)}\n.btn.ghost:hover,.btn.ghost:focus-visible{transform:translateY(-3px);border-color:rgba(127,166,255,.7);background:rgba(127,166,255,.12)}\n.btn:hover svg,.btn:focus-visible svg{transform:translateX(4px)}\n.hero-notes{margin-top:26px;display:flex;flex-wrap:wrap;gap:8px 10px;animation:rise 1s .75s cubic-bezier(.19,.86,.24,1) both}\n.hero-notes li{\n  font-size:12px;color:var(--ink-2);padding:6px 12px;border:1px solid var(--line);border-radius:999px;\n  background:rgba(255,255,255,.03);transition:border-color .3s ease,color .3s ease,transform .3s ease;\n}\n.hero-notes li:hover{border-color:rgba(121,242,192,.5);color:var(--ink);transform:translateY(-2px)}\n\n/* terminal */\n.term-shell{animation:fade 1.2s .5s ease both}\n.term{\n  border:1px solid var(--line);border-radius:12px;overflow:hidden;background:linear-gradient(180deg,rgba(13,18,36,.94),rgba(8,11,22,.96));\n  box-shadow:0 40px 80px -40px rgba(0,0,0,.9), inset 0 1px 0 rgba(255,255,255,.06);\n  transition:transform .5s cubic-bezier(.2,.8,.2,1),box-shadow .5s ease,border-color .5s ease;\n}\n.term:hover,.term:focus-within{transform:translateY(-6px);border-color:rgba(121,242,192,.4);box-shadow:var(--glow),0 40px 80px -40px rgba(0,0,0,.9)}\n.term-bar{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.03)}\n.term-bar i{width:9px;height:9px;border-radius:50%;background:rgba(255,255,255,.2)}\n.term-bar i:nth-child(1){background:rgba(246,194,104,.8)}\n.term-bar i:nth-child(2){background:rgba(121,242,192,.7)}\n.term-bar .tt{margin-left:6px;font-family:var(--mono);font-size:11px;color:var(--ink-3);letter-spacing:.08em}\n.term-bar .tag{margin-left:auto;font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--acc);border:1px solid rgba(121,242,192,.35);border-radius:999px;padding:3px 9px}\n.term-body{padding:18px 16px 14px;font-family:var(--mono);font-size:13px;line-height:1.9;min-height:196px}\n.tl{margin:0 0 6px;word-break:break-word}\n.tl.u{color:var(--ink)}\n.tl.u .p{color:var(--acc);margin-right:8px}\n.tl.m{color:var(--ink-3);font-size:11.5px;letter-spacing:.06em;opacity:0;transition:opacity .4s ease}\n.tl.m.on{opacity:1}\n.tl.b{color:var(--acc-2);white-space:pre-wrap}\n.caret{display:inline-block;width:8px;height:1.05em;background:var(--acc);vertical-align:-.18em;margin-left:2px;animation:blink 1.1s steps(1) infinite}\n.chips{display:flex;flex-wrap:wrap;gap:5px;margin-top:12px}\n.chips b{\n  font-family:var(--mono);font-weight:400;font-size:10.5px;color:var(--ink-3);\n  border:1px solid var(--line);border-radius:3px;padding:1px 6px;background:rgba(255,255,255,.03);\n  animation:sheen 2.6s ease-in-out infinite;transition:color .3s ease,border-color .3s ease;\n}\n.chips b:hover{color:var(--acc);border-color:rgba(121,242,192,.5)}\n.chips b:nth-child(2n){animation-delay:.3s}\n.chips b:nth-child(3n){animation-delay:.6s}\n.chips b:nth-child(4n){animation-delay:.9s}\n.term-cap{margin-top:12px;font-size:11.5px;color:var(--ink-3);font-family:var(--mono);letter-spacing:.06em}\n.scrollcue{\n  position:absolute;left:50%;bottom:22px;transform:translateX(-50%);z-index:2;\n  font-family:var(--mono);font-size:10px;letter-spacing:.28em;color:var(--ink-3);text-align:center;\n}\n.scrollcue::after{content:\"\";display:block;width:1px;height:34px;margin:10px auto 0;background:linear-gradient(180deg,var(--acc),transparent);animation:cue 2.2s ease-in-out infinite}\n\n/* ============ sections ============ */\n.section{position:relative;padding:clamp(78px,11vh,132px) 0}\n.section+.section{border-top:1px solid rgba(150,175,225,.09)}\n.band{position:absolute;inset:0;pointer-events:none;overflow:hidden}\n.sec-head{display:flex;align-items:flex-end;gap:clamp(14px,3vw,34px);flex-wrap:wrap;margin-bottom:clamp(34px,5vw,58px)}\n.sec-ix{font-family:var(--mono);font-size:11px;letter-spacing:.3em;color:var(--acc);padding-bottom:8px}\n.sec-head h2{font-size:clamp(24px,3.4vw,38px);flex:1 1 320px}\n.sec-head p{color:var(--ink-3);max-width:32em;font-size:13.5px;flex:1 1 260px;padding-bottom:4px}\n.rule{height:1px;background:linear-gradient(90deg,var(--acc),rgba(127,166,255,.35),transparent);margin-bottom:clamp(34px,5vw,58px)}\n\n/* cards */\n.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}\n.card{\n  position:relative;padding:28px 24px 24px;border:1px solid var(--line);border-radius:14px;\n  background:linear-gradient(180deg,rgba(255,255,255,.055),rgba(255,255,255,.015));\n  transition:transform .45s cubic-bezier(.2,.8,.2,1),border-color .45s ease,box-shadow .45s ease;overflow:hidden;\n}\n.card::before{\n  content:\"\";position:absolute;inset:0;opacity:0;transition:opacity .45s ease;pointer-events:none;\n  background:radial-gradient(420px 180px at 30% 0%, rgba(121,242,192,.16), transparent 70%);\n}\n.card::after{content:\"\";position:absolute;left:24px;right:auto;top:0;height:2px;width:0;background:linear-gradient(90deg,var(--acc),transparent);transition:width .5s cubic-bezier(.2,.8,.2,1)}\n.card:hover,.card:focus-within{transform:translateY(-8px);border-color:rgba(121,242,192,.42);box-shadow:0 30px 60px -34px rgba(0,0,0,.95)}\n.card:hover::before,.card:focus-within::before{opacity:1}\n.card:hover::after,.card:focus-within::after{width:64%}\n.glyph{width:46px;height:46px;margin-bottom:18px;color:var(--acc)}\n.glyph svg{width:100%;height:100%}\n.card h3{font-size:18px;margin-bottom:12px}\n.card p{color:var(--ink-2);font-size:14px}\n.card .foot{margin-top:16px;padding-top:14px;border-top:1px dashed rgba(150,175,225,.2);font-size:12px;color:var(--ink-3);font-family:var(--mono);letter-spacing:.05em}\n\n/* pipe */\n.pipe{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;align-items:stretch;gap:10px}\n.stage{\n  position:relative;padding:22px 18px;border:1px solid var(--line);border-radius:12px;background:rgba(255,255,255,.04);\n  transition:transform .4s cubic-bezier(.2,.8,.2,1),background .4s ease,border-color .4s ease;\n}\n.stage:hover{transform:translateY(-6px);background:rgba(121,242,192,.09);border-color:rgba(121,242,192,.4)}\n.stage .n{font-family:var(--mono);font-size:10.5px;letter-spacing:.2em;color:var(--acc)}\n.stage h3{font-size:15.5px;margin:8px 0 8px}\n.stage p{font-size:12.5px;color:var(--ink-3);line-height:1.75}\n.wire{position:relative;align-self:center;width:100%;min-width:26px;height:14px;overflow:hidden}\n.wire i{\n  position:absolute;inset:0;display:block;\n  background:repeating-linear-gradient(90deg,var(--acc) 0 7px,transparent 7px 17px);\n  background-size:17px 100%;opacity:.7;animation:wireflow 1.1s linear infinite;\n}\n.branch{\n  margin-top:18px;display:flex;gap:14px;align-items:flex-start;padding:18px 20px;border-radius:12px;\n  border:1px solid rgba(246,194,104,.3);background:rgba(246,194,104,.07);\n}\n.branch svg{width:22px;height:22px;flex:none;color:var(--acc-3)}\n.branch p{font-size:13.5px;color:#f3dfb8}\n.branch b{color:#fff}\n\n/* choose */\n.tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:22px}\n.tab{\n  font-family:var(--sans);font-size:13.5px;font-weight:700;letter-spacing:.03em;color:var(--ink-3);cursor:pointer;\n  padding:11px 18px;border-radius:999px;border:1px solid var(--line);background:rgba(255,255,255,.03);\n  transition:color .3s ease,border-color .3s ease,background .3s ease,transform .3s ease;\n}\n.tab:hover{color:var(--ink);transform:translateY(-2px)}\n.tab[aria-selected=\"true\"]{color:#04140e;background:linear-gradient(120deg,var(--acc),#57dfae);border-color:transparent}\n.panel{padding:26px 24px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.035)}\n.panel.swap{animation:swap .5s cubic-bezier(.2,.8,.2,1)}\n.panel h3{font-size:19px;margin-bottom:10px}\n.panel>p{color:var(--ink-2);font-size:14.5px}\n.panel dl{margin-top:18px;display:grid;gap:12px}\n.panel dl>div{display:grid;grid-template-columns:112px minmax(0,1fr);gap:14px;align-items:baseline;padding-top:12px;border-top:1px dashed rgba(150,175,225,.18)}\n.panel dt{font-family:var(--mono);font-size:11px;letter-spacing:.14em;color:var(--acc)}\n.panel dd{margin:0;font-size:14px;color:var(--ink-2)}\n.tiers{margin-top:16px;display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}\n.tier{padding:22px 20px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(180deg,rgba(127,166,255,.09),rgba(255,255,255,.02));transition:transform .4s cubic-bezier(.2,.8,.2,1),border-color .4s ease}\n.tier:hover{transform:translateY(-6px);border-color:rgba(127,166,255,.55)}\n.tier .k{font-family:var(--mono);font-size:10.5px;letter-spacing:.2em;color:var(--acc-2)}\n.tier h4{margin:8px 0 10px;font-size:16px}\n.tier ul{display:grid;gap:7px}\n.tier li{position:relative;padding-left:16px;font-size:13px;color:var(--ink-2)}\n.tier li::before{content:\"\";position:absolute;left:0;top:.75em;width:7px;height:1px;background:var(--acc-2)}\n.membox{margin-top:26px;padding:24px;border:1px solid var(--line);border-radius:14px;background:rgba(255,255,255,.03);display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:22px;align-items:center}\n.membox h4{font-size:15px;margin-bottom:6px}\n.membox .sub{font-size:12.5px;color:var(--ink-3)}\n.memopts{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:14px}\n.mem{font-family:var(--mono);font-size:12px;letter-spacing:.1em;color:var(--ink-2);cursor:pointer;padding:9px 15px;border-radius:6px;border:1px solid var(--line);background:rgba(255,255,255,.03);transition:all .3s ease}\n.mem:hover{color:var(--ink);border-color:rgba(121,242,192,.5);transform:translateY(-2px)}\n.mem[aria-pressed=\"true\"]{color:var(--acc);border-color:rgba(121,242,192,.7);background:rgba(121,242,192,.12)}\n#memText{font-size:14px;color:var(--ink-2);min-height:3.4em}\n#memText.flash{animation:swap .45s cubic-bezier(.2,.8,.2,1)}\n\n/* steps */\n.steps{position:relative;padding-left:clamp(30px,5vw,58px);--p:1}\n.steps::before{content:\"\";position:absolute;left:8px;top:6px;bottom:6px;width:2px;background:rgba(150,175,225,.16)}\n.steps::after{content:\"\";position:absolute;left:8px;top:6px;width:2px;height:calc(var(--p) * 100%);background:linear-gradient(180deg,var(--acc),var(--acc-2));box-shadow:0 0 14px rgba(121,242,192,.6)}\n.step{position:relative;padding:0 0 34px}\n.step:last-child{padding-bottom:0}\n.step .dot{position:absolute;left:calc(-1 * clamp(30px,5vw,58px));top:4px;width:18px;height:18px;border-radius:50%;background:var(--bg-2);border:2px solid var(--acc);box-shadow:0 0 0 4px rgba(121,242,192,.12);transition:transform .4s cubic-bezier(.2,.8,.2,1),box-shadow .4s ease}\n.step:hover .dot{transform:scale(1.25);box-shadow:0 0 0 7px rgba(121,242,192,.16)}\n.step .ix{font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:var(--acc)}\n.step h3{font-size:18.5px;margin:6px 0 10px}\n.step p{color:var(--ink-2);font-size:14px;max-width:52em}\n.step ul{margin-top:10px;display:flex;flex-wrap:wrap;gap:8px}\n.step li{font-size:12px;color:var(--ink-3);border:1px solid var(--line);border-radius:999px;padding:4px 11px;background:rgba(255,255,255,.03);transition:color .3s ease,border-color .3s ease}\n.step li:hover{color:var(--ink);border-color:rgba(121,242,192,.45)}\n\n/* caveat */\n.warn{display:grid;grid-template-columns:repeat(auto-fit,minmax(255px,1fr));gap:14px}\n.warn article{padding:24px 22px;border-radius:12px;border:1px solid var(--line);background:rgba(255,255,255,.03);transition:transform .4s cubic-bezier(.2,.8,.2,1),border-color .4s ease}\n.warn article:hover{transform:translateY(-6px);border-color:rgba(246,194,104,.5)}\n.warn h3{font-size:15.5px;display:flex;gap:10px;align-items:center;margin-bottom:10px}\n.warn h3 svg{width:18px;height:18px;flex:none;color:var(--acc-3)}\n.warn p{font-size:13.5px;color:var(--ink-2)}\n.note{margin-top:22px;font-family:var(--mono);font-size:12px;letter-spacing:.05em;color:var(--ink-3);border-left:2px solid var(--acc);padding-left:14px}\n\n/* closing */\n.closing{position:relative;padding:clamp(88px,13vh,150px) 0 clamp(70px,10vh,110px);text-align:center;overflow:hidden}\n.closing .halo{position:absolute;left:50%;top:50%;width:min(760px,110vw);aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle,rgba(121,242,192,.16),transparent 62%);animation:breathe 7s ease-in-out infinite;pointer-events:none}\n.closing h2{position:relative;font-size:clamp(26px,4.6vw,48px)}\n.closing p{position:relative;color:var(--ink-2);margin:18px auto 30px;max-width:36em}\n.closing .cta-row{justify-content:center;margin-top:0}\n\nfooter{border-top:1px solid rgba(150,175,225,.12);padding:30px 0 44px}\n.foot{display:flex;flex-wrap:wrap;gap:12px 24px;align-items:center;justify-content:space-between;font-family:var(--mono);font-size:11px;letter-spacing:.12em;color:var(--ink-3)}\n.foot a:hover{color:var(--acc)}\n\n/* dots */\n.dots{position:fixed;right:22px;top:50%;transform:translateY(-50%);z-index:30;display:none;flex-direction:column;gap:14px}\n.dots a{position:relative;width:9px;height:9px;border-radius:50%;background:rgba(150,175,225,.28);transition:background .3s ease,transform .3s ease}\n.dots a span{position:absolute;right:20px;top:50%;transform:translateY(-50%) translateX(6px);opacity:0;white-space:nowrap;font-family:var(--mono);font-size:10px;letter-spacing:.14em;color:var(--ink);background:rgba(10,14,27,.92);border:1px solid var(--line);border-radius:4px;padding:3px 8px;transition:opacity .3s ease,transform .3s ease}\n.dots a:hover,.dots a.active{background:var(--acc);transform:scale(1.35);box-shadow:0 0 12px rgba(121,242,192,.8)}\n.dots a:hover span,.dots a.active span{opacity:1;transform:translateY(-50%) translateX(0)}\n@media (min-width:1000px){.dots{display:flex}}\n\n/* reveal */\n[data-reveal]{opacity:0;transform:translateY(20px);transition:opacity .8s cubic-bezier(.2,.7,.2,1),transform .8s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0ms)}\n[data-reveal].in{opacity:1;transform:none}\n\n/* keyframes */\n@keyframes rise{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}\n@keyframes swipe{to{transform:scaleX(1)}}\n@keyframes fade{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}\n@keyframes blink{0%,100%{opacity:1}50%{opacity:0}}\n@keyframes cue{0%,100%{transform:scaleY(.3);opacity:.4;transform-origin:top}50%{transform:scaleY(1);opacity:1;transform-origin:top}}\n@keyframes wireflow{to{background-position-x:17px}}\n@keyframes pop{0%{opacity:0;transform:translateY(8px) scale(.96)}100%{opacity:1;transform:none}}\n@keyframes swap{0%{opacity:.2;transform:translateY(10px)}100%{opacity:1;transform:none}}\n@keyframes sheen{0%,100%{opacity:.55}50%{opacity:1;color:var(--acc-2)}}\n@keyframes breathe{0%,100%{transform:translate(-50%,-50%) scale(.94);opacity:.75}50%{transform:translate(-50%,-50%) scale(1.06);opacity:1}}\n\n/* ============ responsive ============ */\n@media (max-width:980px){\n  .hero-inner{grid-template-columns:1fr}\n  .term-shell{order:2}\n  .hero{padding-top:96px}\n}\n@media (max-width:640px){\n  .topnav{display:none}\n  .pipe{grid-template-columns:1fr;gap:6px}\n  .wire{height:22px;min-width:0}\n  .wire i{background:repeating-linear-gradient(180deg,var(--acc) 0 7px,transparent 7px 17px);background-size:100% 17px;animation:wireflow-v 1.1s linear infinite}\n  .membox{grid-template-columns:1fr}\n  .panel dl>div{grid-template-columns:1fr;gap:4px}\n  .term-body{font-size:12px;min-height:180px}\n  .section{padding-top:66px}\n}\n@keyframes wireflow-v{to{background-position-y:17px}}\n\n/* ============ motion off ============ */\n.motion-off{scroll-behavior:auto}\n.motion-off *,.motion-off *::before,.motion-off *::after{animation:none!important;transition:none!important}\n.motion-off [data-reveal]{opacity:1!important;transform:none!important}\n.motion-off .par{transform:none!important}\n.motion-off .steps::after{height:100%}\n.motion-off .caret{opacity:1}\n.motion-off .tl.m{opacity:1}\n@media (prefers-reduced-motion:reduce){\n  html{scroll-behavior:auto}\n  *,*::before,*::after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}\n  [data-reveal]{opacity:1!important;transform:none!important}\n}\n\u003c/style>\n\u003cnoscript>\u003cstyle>[data-reveal]{opacity:1!important;transform:none!important}.tl.m{opacity:1!important}\u003c/style>\u003c/noscript>\n\u003c/head>\n\u003cbody>\n\u003ca class=\"skip\" href=\"#steps\">導入手順へスキップ\u003c/a>\n\n\u003cheader class=\"topbar\">\n  \u003cdiv class=\"brand\" aria-hidden=\"true\">\n    \u003csvg viewBox=\"0 0 32 32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\">\n      \u003crect x=\"6\" y=\"6\" width=\"20\" height=\"20\" rx=\"4\" stroke=\"#79f2c0\"/>\n      \u003crect x=\"12\" y=\"12\" width=\"8\" height=\"8\" rx=\"2\" stroke=\"#7fa6ff\"/>\n      \u003cpath d=\"M16 2v4M16 26v4M2 16h4M26 16h4M8 2v3M24 2v3\" stroke=\"#79f2c0\" opacity=\".7\"/>\n    \u003c/svg>\n    \u003cspan>\u003cb>LOCAL\u003c/b> / LLM\u003c/span>\n  \u003c/div>\n  \u003cnav class=\"topnav\" aria-label=\"セクション\">\n    \u003ca href=\"#why\" data-nav>魅力\u003c/a>\n    \u003ca href=\"#flow\" data-nav>仕組み\u003c/a>\n    \u003ca href=\"#choose\" data-nav>えらぶ\u003c/a>\n    \u003ca href=\"#steps\" data-nav>手順\u003c/a>\n    \u003ca href=\"#caveat\" data-nav>注意\u003c/a>\n  \u003c/nav>\n  \u003cbutton class=\"mbtn\" id=\"motionBtn\" type=\"button\" aria-pressed=\"false\">\u003ci aria-hidden=\"true\">\u003c/i>\u003cspan id=\"motionLabel\">動きを止める\u003c/span>\u003c/button>\n\u003c/header>\n\u003cdiv class=\"progress\" aria-hidden=\"true\">\u003cspan id=\"bar\">\u003c/span>\u003c/div>\n\n\u003cmain>\n  \u003c!-- ===================== HERO ===================== -->\n  \u003csection class=\"hero\" id=\"top\">\n    \u003ccanvas id=\"net\" aria-hidden=\"true\">\u003c/canvas>\n    \u003cdiv class=\"hero-veil\" aria-hidden=\"true\">\u003c/div>\n    \u003cdiv class=\"wrap hero-inner\">\n      \u003cdiv>\n        \u003cp class=\"eyebrow\">Run it on your own machine\u003c/p>\n        \u003ch1>\n          \u003cspan class=\"ln\">\u003cspan>モデルを動かす場所を、\u003c/span>\u003c/span>\n          \u003cspan class=\"ln\">\u003cspan>\u003cem>自分のPC\u003c/em>という\u003c/span>\u003c/span>\n          \u003cspan class=\"ln\">\u003cspan>選択肢にふやす。\u003c/span>\u003c/span>\n        \u003c/h1>\n        \u003cp class=\"lead\">ローカルLLMは、サーバーに預けなくても手元の計算機で動く言語モデルです。試す速さ、モデルを選べる自由、データの扱いを自分で設計できる余白があります。特定製品の話ではなく、動かし方の話として。\u003c/p>\n        \u003cp class=\"rot\">\u003cspan class=\"hash\">&gt;\u003c/span>いま試しやすい用途：\u003cspan id=\"rotWord\">文章の下書き\u003c/span>\u003c/p>\n        \u003cdiv class=\"cta-row\">\n          \u003ca class=\"btn primary\" href=\"#steps\">導入の4ステップを見る\n            \u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" aria-hidden=\"true\">\u003cpath d=\"M4 12h14M13 6l6 6-6 6\"/>\u003c/svg>\n          \u003c/a>\n          \u003ca class=\"btn ghost\" href=\"#choose\">用途からモデルをえらぶ\n            \u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" aria-hidden=\"true\">\u003cpath d=\"M6 9l6 6 6-6\"/>\u003c/svg>\n          \u003c/a>\n        \u003c/div>\n        \u003cul class=\"hero-notes\">\n          \u003cli>手元で回す楽しさ\u003c/li>\n          \u003cli>モデルを差し替えられる\u003c/li>\n          \u003cli>データの行き先を設計できる\u003c/li>\n          \u003cli>数値の言い切りなし\u003c/li>\n        \u003c/ul>\n      \u003c/div>\n\n      \u003cdiv class=\"term-shell\">\n        \u003cdiv class=\"term\" tabindex=\"0\">\n          \u003cdiv class=\"term-bar\" aria-hidden=\"true\">\n            \u003ci>\u003c/i>\u003ci>\u003c/i>\n            \u003cspan class=\"tt\">local://session-01\u003c/span>\n            \u003cspan class=\"tag\">画面内の模擬出力\u003c/span>\n          \u003c/div>\n          \u003cdiv class=\"term-body\" aria-hidden=\"true\">\n            \u003cp class=\"tl u\">\u003cspan class=\"p\">›\u003c/span>\u003cspan id=\"tUser\">今日の打ち合わせメモ、3行にまとめて\u003c/span>\u003c/p>\n            \u003cp class=\"tl m on\" id=\"tMeta\">推論は端末の内側で完結（模擬）\u003c/p>\n            \u003cp class=\"tl b\" id=\"tBot\">要点は「期限・担当・未決」の3つ。各1行の案を出します。\u003c/p>\n            \u003cdiv class=\"chips\">\u003cb>tok\u003c/b>\u003cb>打ち合わせ\u003c/b>\u003cb>3行\u003c/b>\u003cb>要点\u003c/b>\u003cb>期限\u003c/b>\u003cb>担当\u003c/b>\u003cb>未決\u003c/b>\u003cb>案\u003c/b>\u003cb>…\u003c/b>\u003c/div>\n          \u003c/div>\n        \u003c/div>\n        \u003cp class=\"term-cap\">※ 送信も保存もしていない、このページ上の演出です。\u003c/p>\n        \u003cp class=\"sr-only\">出力例：打ち合わせメモの要約を頼むと、その場で3行の要約案が返る様子。ページ内で完結する模擬表示で、サーバーへの送信はありません。\u003c/p>\n      \u003c/div>\n    \u003c/div>\n    \u003cp class=\"scrollcue\" aria-hidden=\"true\">SCROLL\u003c/p>\n  \u003c/section>\n\n  \u003c!-- ===================== WHY ===================== -->\n  \u003csection class=\"section\" id=\"why\">\n    \u003cdiv class=\"band\" aria-hidden=\"true\">\n      \u003csvg class=\"par\" data-speed=\"0.08\" viewBox=\"0 0 200 200\" width=\"280\" height=\"280\" style=\"position:absolute;right:-40px;top:40px;opacity:.35\">\n        \u003ccircle cx=\"100\" cy=\"100\" r=\"86\" fill=\"none\" stroke=\"rgba(121,242,192,.5)\" stroke-width=\"1\" stroke-dasharray=\"4 9\"/>\n        \u003ccircle cx=\"100\" cy=\"100\" r=\"56\" fill=\"none\" stroke=\"rgba(127,166,255,.45)\" stroke-width=\"1\"/>\n        \u003ccircle cx=\"100\" cy=\"100\" r=\"4\" fill=\"#79f2c0\"/>\n      \u003c/svg>\n    \u003c/div>\n    \u003cdiv class=\"wrap\">\n      \u003cdiv class=\"sec-head\">\n        \u003cp class=\"sec-ix\">01 / WHY LOCAL\u003c/p>\n        \u003ch2 data-reveal>サーバー前提を、ひとつ外すと見えるもの\u003c/h2>\n        \u003cp data-reveal style=\"--d:80ms\">手元で動かせると、試す回数の重さが変わります。待つ・預けるが減るぶん、気軽に触って削ってを繰り返せます。\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"rule\" aria-hidden=\"true\">\u003c/div>\n      \u003cdiv class=\"grid3\">\n        \u003carticle class=\"card\" data-reveal tabindex=\"0\">\n          \u003cdiv class=\"glyph\" aria-hidden=\"true\">\n            \u003csvg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\">\n              \u003crect x=\"7\" y=\"9\" width=\"34\" height=\"24\" rx=\"3\"/>\n              \u003cpath d=\"M16 39h16M24 33v6\"/>\n              \u003cpath d=\"M13 21l4-5 4 7 4-9 4 6 3-3\" stroke=\"#7fa6ff\"/>\n            \u003c/svg>\n          \u003c/div>\n          \u003ch3>手元で試す楽しさ\u003c/h3>\n          \u003cp>思いついた入力、言い回しの微調整、昨日の失敗のやり直し。起動しておけば、思い立ってから結果を見るまでの距離が短くなります。\u003c/p>\n          \u003cp class=\"foot\">何度やり直しても気にならない環境\u003c/p>\n        \u003c/article>\n        \u003carticle class=\"card\" data-reveal tabindex=\"0\" style=\"--d:90ms\">\n          \u003cdiv class=\"glyph\" aria-hidden=\"true\">\n            \u003csvg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\">\n              \u003cpath d=\"M10 12h28M10 24h28M10 36h28\"/>\n              \u003ccircle cx=\"19\" cy=\"12\" r=\"4.2\" fill=\"#0a0e1b\"/>\n              \u003ccircle cx=\"30\" cy=\"24\" r=\"4.2\" fill=\"#0a0e1b\"/>\n              \u003ccircle cx=\"16\" cy=\"36\" r=\"4.2\" fill=\"#0a0e1b\"/>\n            \u003c/svg>\n          \u003c/div>\n          \u003ch3>用途に合わせて選べる\u003c/h3>\n          \u003cp>軽くして速さ寄り、重くして品質寄り、長い文脈を狙うなど、モデルと設定の組み合わせを替えられます。固定の1択に縛られません。\u003c/p>\n          \u003cp class=\"foot\">サイズ・量子化・設定が選択肢として残る\u003c/p>\n        \u003c/article>\n        \u003carticle class=\"card\" data-reveal tabindex=\"0\" style=\"--d:180ms\">\n          \u003cdiv class=\"glyph\" aria-hidden=\"true\">\n            \u003csvg viewBox=\"0 0 48 48\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\">\n              \u003crect x=\"12\" y=\"21\" width=\"24\" height=\"18\" rx=\"3\"/>\n              \u003cpath d=\"M17 21v-5a7 7 0 0114 0v5\" stroke=\"#7fa6ff\"/>\n              \u003cpath d=\"M24 28v5\"/>\n            \u003c/svg>\n          \u003c/div>\n          \u003ch3>データの扱いを設計できる\u003c/h3>\n          \u003cp>何を入力し、どこに置き、誰と共有するか。自分たちの運用に合わせて決めやすくなります。判断の材料を自分で持てるのが利点です。\u003c/p>\n          \u003cp class=\"foot\">運用ルールを後から説明しやすい\u003c/p>\n        \u003c/article>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- ===================== FLOW ===================== -->\n  \u003csection class=\"section\" id=\"flow\">\n    \u003cdiv class=\"wrap\">\n      \u003cdiv class=\"sec-head\">\n        \u003cp class=\"sec-ix\">02 / HOW IT RUNS\u003c/p>\n        \u003ch2 data-reveal>入力から応答まで、端末の中で起きること\u003c/h2>\n        \u003cp data-reveal style=\"--d:80ms\">仕組みは単純な流れの繰り返しです。外に出る工程を自分で把握できるのが、ローカル実行の性質です。\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"rule\" aria-hidden=\"true\">\u003c/div>\n      \u003col class=\"pipe\">\n        \u003cli class=\"stage\" data-reveal>\n          \u003cspan class=\"n\">STAGE 01\u003c/span>\n          \u003ch3>入力を受け取る\u003c/h3>\n          \u003cp>依頼文と、必要なら手元の資料やコードの抜粋を渡します。\u003c/p>\n        \u003c/li>\n        \u003cli class=\"wire\" aria-hidden=\"true\">\u003ci>\u003c/i>\u003c/li>\n        \u003cli class=\"stage\" data-reveal style=\"--d:80ms\">\n          \u003cspan class=\"n\">STAGE 02\u003c/span>\n          \u003ch3>ばらして考える\u003c/h3>\n          \u003cp>入力を書片の小さな単位に分解し、モデル内の演算を順に通します。\u003c/p>\n        \u003c/li>\n        \u003cli class=\"wire\" aria-hidden=\"true\" aria-hidden=\"true\">\u003ci>\u003c/i>\u003c/li>\n        \u003cli class=\"stage\" data-reveal style=\"--d:160ms\">\n          \u003cspan class=\"n\">STAGE 03\u003c/span>\n          \u003ch3>手元で計算\u003c/h3>\n          \u003cp>CPUやGPUが積まれたモデルの重みに沿って、次の書片を決めていきます。\u003c/p>\n        \u003c/li>\n        \u003cli class=\"wire\" aria-hidden=\"true\">\u003ci>\u003c/i>\u003c/li>\n        \u003cli class=\"stage\" data-reveal style=\"--d:240ms\">\n          \u003cspan class=\"n\">STAGE 04\u003c/span>\n          \u003ch3>応答を返す\u003c/h3>\n          \u003cp>出てきた文章を自分の環境で確認し、必要なら貼り直して続けます。\u003c/p>\n        \u003c/li>\n      \u003c/ol>\n      \u003cdiv class=\"branch\" data-reveal>\n        \u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" aria-hidden=\"true\">\u003cpath d=\"M12 3v11M12 18v3M4 10l8-7 8 7\" />\u003ccircle cx=\"12\" cy=\"18\" r=\"1.6\" fill=\"currentColor\" stroke=\"none\"/>\u003c/svg>\n        \u003cp>\u003cb>ただし「ローカルだけ」が条件ではありません。\u003c/b>検索・API連携・同期などの機能をつけると、その分工夫はしますが通信が発生します。どの工程を外に出すかを設定で決める、という考え方になります。\u003c/p>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- ===================== CHOOSE ===================== -->\n  \u003csection class=\"section\" id=\"choose\">\n    \u003cdiv class=\"band\" aria-hidden=\"true\">\n      \u003csvg class=\"par\" data-speed=\"0.1\" viewBox=\"0 0 120 120\" width=\"180\" height=\"180\" style=\"position:absolute;left:-30px;bottom:20px;opacity:.3\">\n        \u003cpath d=\"M10 110V10M10 110h100\" stroke=\"rgba(127,166,255,.6)\" stroke-width=\"1\"/>\n        \u003cpath d=\"M10 92c22 0 26-40 48-40s26 24 48 24\" fill=\"none\" stroke=\"rgba(121,242,192,.7)\" stroke-width=\"1.6\"/>\n      \u003c/svg>\n    \u003c/div>\n    \u003cdiv class=\"wrap\">\n      \u003cdiv class=\"sec-head\">\n        \u003cp class=\"sec-ix\">03 / CHOOSE\u003c/p>\n        \u003ch2 data-reveal>「何をしたいか」から逆算してえらぶ\u003c/h2>\n        \u003cp data-reveal style=\"--d:80ms\">性能の言い比べより、用途に合う形を選ぶほうが近道です。タブで想定を変えてお試しください。\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"rule\" aria-hidden=\"true\">\u003c/div>\n\n      \u003cdiv class=\"tabs\" role=\"tablist\" aria-label=\"用途でえらぶ\">\n        \u003cbutton class=\"tab\" role=\"tab\" id=\"tb1\" aria-controls=\"tp1\" aria-selected=\"true\" tabindex=\"0\">文章の下書き\u003c/button>\n        \u003cbutton class=\"tab\" role=\"tab\" id=\"tb2\" aria-controls=\"tp2\" aria-selected=\"false\" tabindex=\"-1\">コードの相談\u003c/button>\n        \u003cbutton class=\"tab\" role=\"tab\" id=\"tb3\" aria-controls=\"tp3\" aria-selected=\"false\" tabindex=\"-1\">手元資料の整理\u003c/button>\n      \u003c/div>\n\n      \u003cdiv class=\"panel\" role=\"tabpanel\" id=\"tp1\" aria-labelledby=\"tb1\" tabindex=\"0\">\n        \u003ch3>自分の書き出しを、置いて戻される相手として使う\u003c/h3>\n        \u003cp>一から書かせると迷う場面も、元の文を渡せば直線の相談になります。短い文を何度も行き来する使い方なら、軽く動きやすい構成から始めると続きやすいです。\u003c/p>\n        \u003cdl>\n          \u003cdiv>\u003cdt>入り口の練習\u003c/dt>\u003cdd>書けた段落を1つ貼り、「トーン違いの案を3つ」と頼む。\u003c/dd>\u003c/div>\n          \u003cdiv>\u003cdt>向けやすい形\u003c/dt>\u003cdd>軽量〜中程度・応答が早い構成。長い指示より短い指示を繰り返す。\u003c/dd>\u003c/div>\n          \u003cdiv>\u003cdt>やめどきの目安\u003c/dt>\u003cdd>直したい箇所が毎回同じなら、モデルより指示文を直したほうが早い。\u003c/dd>\u003c/div>\n        \u003c/dl>\n      \u003c/div>\n      \u003cdiv class=\"panel\" role=\"tabpanel\" id=\"tp2\" aria-labelledby=\"tb2\" tabindex=\"0\" hidden>\n        \u003ch3>エラー文と断片を貼って、見当 together に相談する\u003c/h3>\n        \u003cp>ファイル全体を渡すより、疑わしい範囲とエラーの全文を渡すほうが展開が速くなります。文脈を長く持つほど端末の負担は増えるので、載せる範囲を絞る工夫が効きます。\u003c/p>\n        \u003cdl>\n          \u003cdiv>\u003cdt>入り口の練習\u003c/dt>\u003cdd>tracebackの全文＋該当数行を貼り、原因の候補を出してもらう。\u003c/dd>\u003c/div>\n          \u003cdiv>\u003cdt>向けやすい形\u003c/dt>\u003cdd>ある程度まとまった文脈を扱える構成。ログは要点だけ抜く。\u003c/dd>\u003c/div>\n          \u003cdiv>\u003cdt>やめどきの目安\u003c/dt>\u003cdd>動作確認は自分でする前提で、案の出し手に留めると事故が減る。\u003c/dd>\u003c/div>\n        \u003c/dl>\n      \u003c/div>\n      \u003cdiv class=\"panel\" role=\"tabpanel\" id=\"tp3\" aria-labelledby=\"tb3\" tabindex=\"0\" hidden>\n        \u003ch3>手元の資料を、分類と要約の作業台に載せる\u003c/h3>\n        \u003cp>ローカルに置いた資料を貼り付けて、見出しごとに分ける・論点だけ抜き出す、という使い方です。外部機能をつなげない構成なら、入力の内容はこの端末の中に留まります。\u003c/p>\n        \u003cdl>\n          \u003cdiv>\u003cdt>入り口の練習\u003c/dt>\u003cdd>1本の資料を貼り、「ラベル3種類で分類して」と頼む。\u003c/dd>\u003c/div>\n          \u003cdiv>\u003cdt>向けやすい形\u003c/dt>\u003cdd>長め入力を扱える構成。分類基準を先に指定すると再現しやすい。\u003c/dd>\u003c/div>\n          \u003cdiv>\u003cdt>やめどきの目安\u003c/dt>\u003cdd>検索や連携を入れるときは、通信の有無を先に設定で確認する。\u003c/dd>\u003c/div>\n        \u003c/dl>\n      \u003c/div>\n\n      \u003cdiv class=\"tiers\">\n        \u003carticle class=\"tier\" data-reveal tabindex=\"0\">\n          \u003cp class=\"k\">TYPE A\u003c/p>\n          \u003ch4>軽量・手軽さ寄り\u003c/h4>\n          \u003cul>\n            \u003cli>短い入力の往復に向く\u003c/li>\n            \u003cli>古い端末でも狙いやすい\u003c/li>\n            \u003cli>長い文脈や凝った指定は苦手になりやすい\u003c/li>\n          \u003c/ul>\n        \u003c/article>\n        \u003carticle class=\"tier\" data-reveal tabindex=\"0\" style=\"--d:90ms\">\n          \u003cp class=\"k\">TYPE B\u003c/p>\n          \u003ch4>バランス寄り\u003c/h4>\n          \u003cul>\n            \u003cli>用途を絞った実用に合わせやすい\u003c/li>\n            \u003cli>差し替えの比較基準にしやすい\u003c/li>\n            \u003cli>設定を詰めると急に重くなる余地あり\u003c/li>\n          \u003c/ul>\n        \u003c/article>\n        \u003carticle class=\"tier\" data-reveal tabindex=\"0\" style=\"--d:180ms\">\n          \u003cp class=\"k\">TYPE C\u003c/p>\n          \u003ch4>品質・長文脈寄り\u003c/h4>\n          \u003cul>\n            \u003cli>長い資料や凝った指示に強い狙い\u003c/li>\n            \u003cli>メモリと計算の余裕が前提\u003c/li>\n            \u003cli>応答まで待つ前提の運用になる\u003c/li>\n          \u003c/ul>\n        \u003c/article>\n      \u003c/div>\n\n      \u003cdiv class=\"membox\" data-reveal>\n        \u003cdiv>\n          \u003ch4>搭載メモリから見る、はじめ方\u003c/h4>\n          \u003cp class=\"sub\">あくまではじめ方の目安です。実際の必要量と体感は、モデル・量子化・設定・機器で動きます。\u003c/p>\n        \u003c/div>\n        \u003cdiv>\n          \u003cdiv class=\"memopts\" role=\"group\" aria-label=\"搭載メモリで絞り込む\">\n            \u003cbutton class=\"mem\" type=\"button\" data-mem=\"0\" aria-pressed=\"true\">8GB\u003c/button>\n            \u003cbutton class=\"mem\" type=\"button\" data-mem=\"1\" aria-pressed=\"false\">16GB\u003c/button>\n            \u003cbutton class=\"mem\" type=\"button\" data-mem=\"2\" aria-pressed=\"false\">32GB以上\u003c/button>\n          \u003c/div>\n          \u003cp id=\"memText\">小さめ・量子化されたモデルから試すのが近道です。長文脈や重い設定は苦手にしやすいので、用途を1つに絞って1つずつ確かめる形になります。\u003c/p>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- ===================== STEPS ===================== -->\n  \u003csection class=\"section\" id=\"steps\">\n    \u003cdiv class=\"wrap\">\n      \u003cdiv class=\"sec-head\">\n        \u003cp class=\"sec-ix\">04 / STEPS\u003c/p>\n        \u003ch2 data-reveal>導入は、4つの順番で考える\u003c/h2>\n        \u003cp data-reveal style=\"--d:80ms\">機器から決めると用途が歪みます。用件のほうを先に決めるのが、遠回りの少ない流れです。\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"rule\" aria-hidden=\"true\">\u003c/div>\n      \u003col class=\"steps\" id=\"stepList\">\n        \u003cli class=\"step\" data-reveal>\n          \u003cspan class=\"dot\" aria-hidden=\"true\">\u003c/span>\n          \u003cp class=\"ix\">STEP 01\u003c/p>\n          \u003ch3>用途を決める\u003c/h3>\n          \u003cp>「下書きの手伝い」「コードの相談」「手元資料の整理」のどれを主にするか、一文で書いておきます。ここが曖昧だと、之后的な選択が全部ブレます。\u003c/p>\n          \u003cul>\u003cli>任せたいことを一文で\u003c/li>\u003cli>1日何回使う想定か\u003c/li>\u003cli>失敗しても困らない範囲から\u003c/li>\u003c/ul>\n        \u003c/li>\n        \u003cli class=\"step\" data-reveal style=\"--d:80ms\">\n          \u003cspan class=\"dot\" aria-hidden=\"true\">\u003c/span>\n          \u003cp class=\"ix\">STEP 02\u003c/p>\n          \u003ch3>機器と必要メモリを確認する\u003c/h3>\n          \u003cp>搭載メモリ、グラフィックスの有無、使えるディスク容量を数えます。ここが次のモデル選びの上限になるので、推測で進めません。\u003c/p>\n          \u003cul>\u003cli>メモリ搭載量\u003c/li>\u003cli>GPUの有無とVRAM\u003c/li>\u003cli>モデル分の空き容量\u003c/li>\u003c/ul>\n        \u003c/li>\n        \u003cli class=\"step\" data-reveal style=\"--d:160ms\">\n          \u003cspan class=\"dot\" aria-hidden=\"true\">\u003c/span>\n          \u003cp class=\"ix\">STEP 03\u003c/p>\n          \u003ch3>利用条件を読んでモデルを選ぶ\u003c/h3>\n          \u003cp>モデルには使い方・再配布・商用利用の条件が添えられていることがあります。全モデルが無料で商用利用できるとは限らないため、公開されている条件文と説明を確認してから選びます。\u003c/p>\n          \u003cul>\u003cli>条件文を読む\u003c/li>\u003cli>対応言語や入力長を見る\u003c/li>\u003cli>必要なら複数候補を持つ\u003c/li>\u003c/ul>\n        \u003c/li>\n        \u003cli class=\"step\" data-reveal style=\"--d:240ms\">\n          \u003cspan class=\"dot\" aria-hidden=\"true\">\u003c/span>\n          \u003cp class=\"ix\">STEP 04\u003c/p>\n          \u003ch3>小さく試す\u003c/h3>\n          \u003cp>短い入力で1往復。待つ時間が耐えられるか、出る文章が実用になるかを見て、必要ならモデルか設定だけを差し替えます。変えるものは一度に1つにすると原因が残ります。\u003c/p>\n          \u003cul>\u003cli>短い入力で1往復\u003c/li>\u003cli>変えるのは一度に1つ\u003c/li>\u003cli>失敗例もメモしておく\u003c/li>\u003c/ul>\n        \u003c/li>\n      \u003c/ol>\n      \u003cp class=\"note\" data-reveal>ページ内のCTAはこの手順までを結ぶリンクで、入力内容や個人情報をどこかへ送る仕組みはありません。\u003c/p>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- ===================== CAVEAT ===================== -->\n  \u003csection class=\"section\" id=\"caveat\">\n    \u003cdiv class=\"wrap\">\n      \u003cdiv class=\"sec-head\">\n        \u003cp class=\"sec-ix\">05 / CAUTION\u003c/p>\n        \u003ch2 data-reveal>かっこよさの裏に、決めておくこと\u003c/h2>\n        \u003cp data-reveal style=\"--d:80ms\">このページでは未測定の数値や順位は置いていません。代わりに、始める前に効いてくる注意を残します。\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"rule\" aria-hidden=\"true\">\u003c/div>\n      \u003cdiv class=\"warn\">\n        \u003carticle data-reveal tabindex=\"0\">\n          \u003ch3>\u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" aria-hidden=\"true\">\u003ccircle cx=\"12\" cy=\"12\" r=\"9\"/>\u003cpath d=\"M12 7v6l4 2\"/>\u003c/svg>速さとメモリは依存する\u003c/h3>\n          \u003cp>体感の速さも必要な容量も、モデル・機器・設定で変わります。人の環境をそのまま自分の想定に持ち込まないほうが安全です。\u003c/p>\n        \u003c/article>\n        \u003carticle data-reveal tabindex=\"0\" style=\"--d:90ms\">\n          \u003ch3>\u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" aria-hidden=\"true\">\u003cpath d=\"M4 6h16v12H4z\"/>\u003cpath d=\"M4 10h16M9 14h6\"/>\u003c/svg>無料・商用利用とは限らない\u003c/h3>\n          \u003cp>手元で動くことと、使い方の条件は別の話です。モデルごとに公開された条件を確認し、業務利用なら記録を残しておきます。\u003c/p>\n        \u003c/article>\n        \u003carticle data-reveal tabindex=\"0\" style=\"--d:180ms\">\n          \u003ch3>\u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" aria-hidden=\"true\">\u003cpath d=\"M12 3l8 4v6c0 4-4 7-8 8-4-1-8-4-8-8V7z\"/>\u003cpath d=\"M9 12h6\"/>\u003c/svg>秘密保持は自動ではない\u003c/h3>\n          \u003cp>外部連携や設定の選び方次第で通信は起きます。完全な内側で完結させるには、どこで通信するかを自分で点検する必要があります。\u003c/p>\n        \u003c/article>\n        \u003carticle data-reveal tabindex=\"0\" style=\"--d:270ms\">\n          \u003ch3>\u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.9\" aria-hidden=\"true\">\u003cpath d=\"M5 19V5h14\"/>\u003cpath d=\"M8 15l4-6 3 4 3-6\"/>\u003c/svg>成功と精度も条件付き\u003c/h3>\n          \u003cp>うまくいくかも、出た文章が使えるかも、用途とモデルに依存します。小さく試して自分で確かめる順番を大事にしてください。\u003c/p>\n        \u003c/article>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\n  \u003c!-- ===================== CLOSING ===================== -->\n  \u003csection class=\"closing\" id=\"closing\">\n    \u003cdiv class=\"halo\" aria-hidden=\"true\">\u003c/div>\n    \u003cdiv class=\"wrap\">\n      \u003ch2 data-reveal>まずは、用途を一文書いてみる。\u003c/h2>\n      \u003cp data-reveal style=\"--d:90ms\">場所の選択肢が増えると、試す回数が増えます。回数が増えると、自分の使い方が決まります。\u003c/p>\n      \u003cdiv class=\"cta-row\" data-reveal style=\"--d:180ms\">\n        \u003ca class=\"btn primary\" href=\"#steps\">STEP 01 から始める\n          \u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" aria-hidden=\"true\">\u003cpath d=\"M4 12h14M13 6l6 6-6 6\"/>\u003c/svg>\n        \u003c/a>\n        \u003ca class=\"btn ghost\" href=\"#top\">最初の画面へ戻る\n          \u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" aria-hidden=\"true\">\u003cpath d=\"M6 15l6-6 6 6\"/>\u003c/svg>\n        \u003c/a>\n      \u003c/div>\n    \u003c/div>\n  \u003c/section>\n\u003c/main>\n\n\u003cfooter>\n  \u003cdiv class=\"wrap foot\">\n    \u003cspan>LOCAL / LLM — テーマ紹介ページ（特定製品の販売サイトではありません）\u003c/span>\n    \u003cspan>数値・実績の断定なし / ページ内で完結 / \u003ca href=\"#top\">PAGE TOP\u003c/a>\u003c/span>\n  \u003c/div>\n\u003c/footer>\n\n\u003cnav class=\"dots\" aria-label=\"セクション送り\">\n  \u003ca href=\"#top\" data-nav aria-label=\"先頭へ\">\u003cspan>TOP\u003c/span>\u003c/a>\n  \u003ca href=\"#why\" data-nav aria-label=\"魅力へ\">\u003cspan>WHY\u003c/span>\u003c/a>\n  \u003ca href=\"#flow\" data-nav aria-label=\"仕組みへ\">\u003cspan>HOW\u003c/span>\u003c/a>\n  \u003ca href=\"#choose\" data-nav aria-label=\"えらぶへ\">\u003cspan>CHOOSE\u003c/span>\u003c/a>\n  \u003ca href=\"#steps\" data-nav aria-label=\"手順へ\">\u003cspan>STEPS\u003c/span>\u003c/a>\n  \u003ca href=\"#caveat\" data-nav aria-label=\"注意へ\">\u003cspan>CAUTION\u003c/span>\u003c/a>\n\u003c/nav>\n\n\u003cscript>\n(function(){\n  'use strict';\n  var root = document.documentElement;\n  var rmq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : {matches:false, addEventListener:null};\n  var motionOn = !rmq.matches;\n  var motionBtn = document.getElementById('motionBtn');\n  var motionLabel = document.getElementById('motionLabel');\n\n  /* ---------- 1. hero canvas: token graph ---------- */\n  var cv = document.getElementById('net');\n  var ctx = cv && cv.getContext ? cv.getContext('2d') : null;\n  var W = 0, H = 0, NODES = [], LINKS = [], PULSES = [], raf = 0, last = 0;\n  var ptr = {x:0.5, y:0.5}, ptrTarget = {x:0.5, y:0.5};\n\n  function sizeCanvas(){\n    if(!ctx) return;\n    var host = cv.parentNode;\n    W = Math.max(320, host.clientWidth);\n    H = Math.max(320, host.clientHeight);\n    var dpr = Math.min(window.devicePixelRatio || 1, 2);\n    cv.width = Math.round(W * dpr);\n    cv.height = Math.round(H * dpr);\n    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n    build();\n  }\n  function build(){\n    NODES = []; LINKS = []; PULSES = [];\n    var cols = W \u003c 640 ? 4 : 7, rows = W \u003c 640 ? 7 : 5;\n    for(var c=0; c\u003ccols; c++){\n      for(var r=0; r\u003crows; r++){\n        NODES.push({\n          x:(c+.5)/cols*W + (Math.random()-.5)*W/cols*.75,\n          y:(r+.5)/rows*H + (Math.random()-.5)*H/rows*.75,\n          ph:Math.random()*6.28, nb:[]\n        });\n      }\n    }\n    for(var i=0;i\u003cNODES.length;i++){\n      var d=[];\n      for(var j=0;j\u003cNODES.length;j++){\n        if(i===j) continue;\n        var dx=NODES[i].x-NODES[j].x, dy=NODES[i].y-NODES[j].y;\n        d.push({k:dx*dx+dy*dy, j:j});\n      }\n      d.sort(function(a,b){return a.k-b.k;});\n      for(var t=0;t\u003c2 && t\u003cd.length;t++){\n        var to=d[t].j, lo=Math.min(i,to), hi=Math.max(i,to), key=lo+'-'+hi, found=-1;\n        for(var m=0;m\u003cLINKS.length;m++){ if(LINKS[m].key===key){ found=m; break; } }\n        if(found\u003c0){ LINKS.push({key:key,a:lo,b:hi}); found=LINKS.length-1; }\n        NODES[i].nb.push(found);\n      }\n    }\n    for(var p=0;p\u003cMath.min(16, LINKS.length);p++){\n      PULSES.push({li:Math.floor(Math.random()*LINKS.length), t:Math.random(), sp:.22+Math.random()*.5, hue:Math.random()\u003c.35?0:1});\n    }\n  }\n  function paint(dt){\n    if(!ctx) return;\n    ctx.clearRect(0,0,W,H);\n    ptr.x += (ptrTarget.x-ptr.x)*.06;\n    ptr.y += (ptrTarget.y-ptr.y)*.06;\n    ctx.save();\n    ctx.translate((ptr.x-.5)*22, (ptr.y-.5)*14);\n    var i, a, b;\n    ctx.lineWidth = 1;\n    ctx.strokeStyle = 'rgba(150,175,225,.13)';\n    ctx.beginPath();\n    for(i=0;i\u003cLINKS.length;i++){\n      a=NODES[LINKS[i].a]; b=NODES[LINKS[i].b];\n      ctx.moveTo(a.x,a.y); ctx.lineTo(b.x,b.y);\n    }\n    ctx.stroke();\n    var t = last/1000;\n    for(i=0;i\u003cNODES.length;i++){\n      var n=NODES[i], br=.28+Math.sin(t*1.4+n.ph)*.18;\n      ctx.fillStyle='rgba(127,166,255,'+br.toFixed(3)+')';\n      ctx.beginPath(); ctx.arc(n.x,n.y,1.9,0,6.283); ctx.fill();\n    }\n    for(i=0;i\u003cPULSES.length;i++){\n      var p=PULSES[i];\n      p.t += dt*p.sp;\n      if(p.t>=1){\n        var cur=LINKS[p.li], at=p.hue===1?cur.b:cur.a, nb=NODES[at].nb;\n        if(nb.length){ p.li=nb[Math.floor(Math.random()*nb.length)]; }\n        p.t=0; p.sp=.22+Math.random()*.5;\n      }\n      var L=LINKS[p.li]; if(!L) continue;\n      var A=NODES[L.a], B=NODES[L.b];\n      var x=A.x+(B.x-A.x)*p.t, y=A.y+(B.y-A.y)*p.t;\n      var col = p.hue ? 'rgba(127,166,255,' : 'rgba(121,242,192,';\n      ctx.shadowBlur=14; ctx.shadowColor=col+'.85)';\n      ctx.fillStyle=col+'.95)';\n      ctx.beginPath(); ctx.arc(x,y,2.4,0,6.283); ctx.fill();\n      ctx.shadowBlur=0;\n      var gt=ctx.createRadialGradient(x,y,0,x,y,34);\n      gt.addColorStop(0,col+'.20)'); gt.addColorStop(1,col+'0)');\n      ctx.fillStyle=gt; ctx.beginPath(); ctx.arc(x,y,34,0,6.283); ctx.fill();\n    }\n    ctx.restore();\n  }\n  function frame(ts){\n    var dt = Math.min(40, (ts - last) || 16) / 1000;\n    last = ts || 0;\n    paint(dt);\n    raf = requestAnimationFrame(frame);\n  }\n  function startCanvas(){\n    if(!ctx || raf) return;\n    last = performance.now ? performance.now() : 0;\n    raf = requestAnimationFrame(frame);\n  }\n  function stopCanvas(){ if(raf){ cancelAnimationFrame(raf); raf = 0; } }\n  if(ctx){\n    sizeCanvas();\n    paint(0);\n    window.addEventListener('resize', function(){\n      var was = !!raf; stopCanvas(); sizeCanvas(); paint(0); if(motionOn && !was) startCanvas(); else if(motionOn) startCanvas();\n    });\n    window.addEventListener('pointermove', function(e){\n      ptrTarget.x = e.clientX / (window.innerWidth || 1);\n      ptrTarget.y = e.clientY / (window.innerHeight || 1);\n    }, {passive:true});\n    document.addEventListener('visibilitychange', function(){\n      if(document.hidden){ stopCanvas(); } else if(motionOn){ startCanvas(); }\n    });\n  }\n\n  /* ---------- 2. terminal typing ---------- */\n  var SCRIPTS = [\n    {u:'今日の打ち合わせメモ、3行にまとめて', m:'推論は端末の内側で完結（模擬）', b:'要点は「期限・担当・未決」の3つ。各1行の案を出します。'},\n    {u:'この例外、直し所の見当をつけて', m:'抜粋とエラー文だけを渡す構成（模擬）', b:'tracebackの行番号付近と、渡している型を確かめたいです。'},\n    {u:'手元の資料を論点ごとに分類して', m:'通信なしの構成 / 設定は確認ずみ（模擬）', b:'見出し単位で分けます。ラベル名を先に指定すると再現します。'}\n  ];\n  var tU = document.getElementById('tUser'), tM = document.getElementById('tMeta'), tB = document.getElementById('tBot');\n  var sIdx = 0, phase = 0, cursor = 0, timer = 0;\n  function stopType(){ if(timer){ clearTimeout(timer); timer = 0; } }\n  function resetTerm(){ tU.textContent=''; tB.textContent=''; tM.classList.remove('on'); phase=0; cursor=0; }\n  function showStatic(){\n    var s = SCRIPTS[sIdx];\n    tU.textContent = s.u; tM.textContent = s.m; tM.classList.add('on'); tB.textContent = s.b;\n  }\n  function typeStep(){\n    if(!motionOn) return;\n    var s = SCRIPTS[sIdx];\n    if(phase === 0){\n      cursor++; tU.textContent = s.u.slice(0, cursor);\n      if(cursor >= s.u.length){ phase = 1; cursor = 0; timer = setTimeout(typeStep, 340); return; }\n      timer = setTimeout(typeStep, 34);\n    } else if(phase === 1){\n      tM.textContent = s.m; tM.classList.add('on'); phase = 2; timer = setTimeout(typeStep, 420);\n    } else if(phase === 2){\n      cursor++; tB.textContent = s.b.slice(0, cursor);\n      if(cursor >= s.b.length){ phase = 3; timer = setTimeout(typeStep, 2600); return; }\n      timer = setTimeout(typeStep, 26);\n    } else {\n      sIdx = (sIdx + 1) % SCRIPTS.length;\n      resetTerm(); timer = setTimeout(typeStep, 260);\n    }\n  }\n  function startType(){ if(motionOn && !timer){ resetTerm(); timer = setTimeout(typeStep, 400); } }\n  if(!motionOn) showStatic();\n\n  /* ---------- 3. rotator ---------- */\n  var WORDS = ['文章の下書き','コードの相談','手元資料の整理','要案の書き直し'], wI = 0;\n  var rot = document.getElementById('rotWord'), rotTimer = 0;\n  function rotTick(){\n    if(!motionOn) return;\n    wI = (wI + 1) % WORDS.length;\n    rot.textContent = WORDS[wI];\n    rot.classList.remove('pop');\n    void rot.offsetWidth;\n    rot.classList.add('pop');\n  }\n  function startRot(){ if(motionOn && !rotTimer) rotTimer = setInterval(rotTick, 2600); }\n  function stopRot(){ if(rotTimer){ clearInterval(rotTimer); rotTimer = 0; } }\n\n  /* ---------- 4. reveal + active nav ---------- */\n  var revealEls = [].slice.call(document.querySelectorAll('[data-reveal]'));\n  if('IntersectionObserver' in window){\n    var io = new IntersectionObserver(function(es){\n      es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });\n    }, {threshold:.08, rootMargin:'0px 0px -10% 0px'});\n    revealEls.forEach(function(el, i){\n      if(!el.style.getPropertyValue('--d')) el.style.setProperty('--d', (i % 4) * 70 + 'ms');\n      io.observe(el);\n    });\n    var links = [].slice.call(document.querySelectorAll('[data-nav]'));\n    var so = new IntersectionObserver(function(es){\n      es.forEach(function(e){\n        if(!e.isIntersecting) return;\n        links.forEach(function(l){ l.classList.toggle('active', l.getAttribute('href') === '#' + e.target.id); });\n      });\n    }, {rootMargin:'-45% 0px -45% 0px'});\n    [].forEach.call(document.querySelectorAll('main section[id]'), function(s){ so.observe(s); });\n  } else {\n    revealEls.forEach(function(el){ el.classList.add('in'); });\n  }\n\n  /* ---------- 5. scroll linked ---------- */\n  var bar = document.getElementById('bar');\n  var stepList = document.getElementById('stepList');\n  var pars = [].slice.call(document.querySelectorAll('.par'));\n  function onScroll(){\n    var vh = window.innerHeight || 1;\n    var max = document.documentElement.scrollHeight - vh;\n    var st = window.pageYOffset || document.documentElement.scrollTop || 0;\n    if(bar) bar.style.transform = 'scaleX(' + (max > 0 ? Math.min(1, Math.max(0, st / max)) : 1).toFixed(4) + ')';\n    if(stepList){\n      var r = stepList.getBoundingClientRect();\n      var p = (vh * .82 - r.top) / (r.height + 1);\n      stepList.style.setProperty('--p', Math.min(1, Math.max(0, p)).toFixed(3));\n    }\n    for(var i=0;i\u003cpars.length;i++){\n      var el = pars[i], rr = el.getBoundingClientRect();\n      var c = (rr.top + rr.height/2 - vh/2) / vh;\n      var sp = parseFloat(el.getAttribute('data-speed') || '.06');\n      el.style.transform = 'translate3d(0,' + (-c * sp * 200).toFixed(1) + 'px,0)';\n    }\n  }\n  var queued = false;\n  window.addEventListener('scroll', function(){\n    if(queued) return;\n    queued = true;\n    requestAnimationFrame(function(){ queued = false; onScroll(); });\n  }, {passive:true});\n  onScroll();\n\n  /* ---------- 6. tabs ---------- */\n  var tabs = [].slice.call(document.querySelectorAll('[role=\"tab\"]'));\n  var panels = [].slice.call(document.querySelectorAll('[role=\"tabpanel\"]'));\n  function selectTab(tab, move){\n    tabs.forEach(function(t){\n      var on = t === tab;\n      t.setAttribute('aria-selected', String(on));\n      t.tabIndex = on ? 0 : -1;\n    });\n    panels.forEach(function(p){ p.hidden = p.id !== tab.getAttribute('aria-controls'); });\n    var act = document.getElementById(tab.getAttribute('aria-controls'));\n    if(act && motionOn){ act.classList.remove('swap'); void act.offsetWidth; act.classList.add('swap'); }\n    if(move) tab.focus();\n  }\n  tabs.forEach(function(t, i){\n    t.addEventListener('click', function(){ selectTab(t, false); });\n    t.addEventListener('keydown', function(e){\n      var k = e.key, n = null;\n      if(k === 'ArrowRight') n = tabs[(i+1) % tabs.length];\n      else if(k === 'ArrowLeft') n = tabs[(i-1+tabs.length) % tabs.length];\n      else if(k === 'Home') n = tabs[0];\n      else if(k === 'End') n = tabs[tabs.length-1];\n      if(n){ e.preventDefault(); selectTab(n, true); }\n    });\n  });\n\n  /* ---------- 7. memory widget ---------- */\n  var MEM = [\n    '小さめ・量子化されたモデルから試すのが近道です。長文脈や重い設定は苦手にしやすいので、用途を1つに絞って1つずつ確かめる形になります。',\n    '中くらいの規模まで狙えます。用途を絞って1つずつ試す定番の土台ですが、長文をまとめて扱う設定に寄せると急に余裕がなくなります。',\n    '大きめ・長文脈にも挑戦できます。ただし計算装置の種別や設定の効きが強く、環境を揃えてから比較しないと判断がぶれます。'\n  ];\n  var memBtns = [].slice.call(document.querySelectorAll('.mem'));\n  var memText = document.getElementById('memText');\n  memBtns.forEach(function(b){\n    b.addEventListener('click', function(){\n      memBtns.forEach(function(o){ o.setAttribute('aria-pressed', String(o === b)); });\n      memText.textContent = MEM[parseInt(b.getAttribute('data-mem'), 10) || 0];\n      if(motionOn){ memText.classList.remove('flash'); void memText.offsetWidth; memText.classList.add('flash'); }\n    });\n  });\n\n  /* ---------- 8. motion switch ---------- */\n  function applyMotion(){\n    root.classList.toggle('motion-off', !motionOn);\n    motionBtn.setAttribute('aria-pressed', String(!motionOn));\n    motionLabel.textContent = motionOn ? '動きを止める' : '動きを再開する';\n    if(motionOn){\n      if(!document.hidden) startCanvas();\n      startType(); startRot();\n    } else {\n      stopCanvas(); stopType(); stopRot();\n      if(ctx){ last = 0; paint(0); }\n      showStatic();\n    }\n  }\n  motionBtn.addEventListener('click', function(){ motionOn = !motionOn; applyMotion(); });\n  if(rmq.addEventListener) rmq.addEventListener('change', function(e){ motionOn = !e.matches; applyMotion(); });\n  applyMotion();\n})();\n\u003c/script>\n\u003c/body>\n\u003c/html>"};
